<section class="learn-panel"><div class="learn-grid"><div><h2>Prepara tu espacio</h2><ul class="learn-muted"><li>Usa buena iluminación frontal.</li><li>Mantén manos y rostro dentro del encuadre.</li><li>Coloca el dispositivo en una superficie estable.</li><li>El vídeo permanece en el navegador: esta página no lo sube al servidor.</li></ul><button class="learn-button" id="camera-start" type="button">Activar cámara</button> <button class="learn-button secondary" id="camera-stop" type="button" disabled>Apagar cámara</button><p id="camera-status" class="learn-muted" aria-live="polite">La cámara está apagada.</p></div><div><video id="camera-video" class="learn-video" autoplay playsinline muted></video><div class="learn-progress"><i id="camera-meter" style="width:0%"></i></div><p class="learn-muted">Indicador visual de sesión, no puntuación de reconocimiento.</p></div></div></section>
<script>
(()=>{const v=document.getElementById('camera-video'),s=document.getElementById('camera-status'),on=document.getElementById('camera-start'),off=document.getElementById('camera-stop'),m=document.getElementById('camera-meter');let stream=null,start=0,timer=null;on.addEventListener('click',async()=>{if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){s.textContent='Este navegador no ofrece acceso a cámara o la página no usa HTTPS.';return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});v.srcObject=stream;start=Date.now();on.disabled=true;off.disabled=false;s.textContent='Cámara activa. Practica a tu ritmo.';timer=setInterval(()=>m.style.width=(Math.min(100,((Date.now()-start)/60000)*100))+'%',500)}catch(e){s.textContent=e.name==='NotAllowedError'?'Permiso denegado. Autoriza la cámara desde el navegador.':'No se pudo iniciar la cámara: '+e.message}});function stop(){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;v.srcObject=null;on.disabled=false;off.disabled=true;clearInterval(timer);s.textContent='Cámara apagada.'}off.addEventListener('click',stop);window.addEventListener('pagehide',stop)})();
</script>
